#!/usr/bin/env bash
# M0-028: browser WT/WS interop matrix. One-shot on a clean machine:
#   scripts/run-interop.sh            # chromium + firefox + webkit (whatever is installed; the rest is reported as untested)
#   INSTALL_BROWSERS=1 scripts/run-interop.sh   # run `playwright install` first (CI; needs network)
#   FRONTLINE_INTEROP_BROWSERS=chromium scripts/run-interop.sh
# Output: reports/m0/browser-matrix.{json,md}. The dev certificate is regenerated by the spec on every run (13 days validity).
set -euo pipefail
cd "$(dirname "$0")/.."
export CARGO_INCREMENTAL=${CARGO_INCREMENTAL:-0} CARGO_PROFILE_DEV_DEBUG=${CARGO_PROFILE_DEV_DEBUG:-0}

cargo build -p frontline-server --bins
if [ ! -f crates/sim-wasm/pkg/frontline_sim_wasm.js ]; then
  wasm-pack build crates/sim-wasm --target web --profile wasm-release
fi
if [ "${INSTALL_BROWSERS:-0}" = 1 ]; then
  pnpm -C client exec playwright install --with-deps chromium firefox webkit
fi
status=0
FRONTLINE_REQUIRE_SERVER=1 pnpm -C client exec playwright test -c playwright.interop.config.ts || status=$?
echo
cat reports/m0/browser-matrix.md
exit $status
